# Find and replace page3 content
page3_pattern = re.compile(
    r'(<div id="page3" class="doc-page">.*?<div class="doc-inner">.*?<button[^>]*>.*?</button>)(.*?)(</div>\s*<footer class="site-footer">)',
    re.DOTALL
)

page4_pattern = re.compile(
    r'(<div id="page4" class="doc-page">.*?<div class="doc-inner">.*?<button[^>]*>.*?</button>)(.*?)(</div>\s*<footer class="site-footer">)',
    re.DOTALL
)

new_content = page3_pattern.sub(lambda m: m.group(1) + '\n' + oferta_html + '\n' + m.group(3), content, count=1)
new_content = page4_pattern.sub(lambda m: m.group(1) + '\n' + politika_html + '\n' + m.group(3), new_content, count=1)

